GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def _kvpr(mlist):
    """KVPR of a single GPU's model list."""
    free = GPU_MEM_SIZE - sum(m.model_size for m in mlist)
    if not mlist or free <= 0:
        return 0.0
    return sum(m.req_rate / m.slo for m in mlist) / free


def _greedy(gpu_num, sorted_models):
    """Place each model on the GPU with the lowest current KVPR that fits it."""
    placement = {gpu_id: [] for gpu_id in range(gpu_num)}
    free = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num
    for model in sorted_models:
        best_idx, best_ratio = None, float('inf')
        for gpu_id in range(gpu_num):
            if model.model_size <= free[gpu_id] and free[gpu_id] > 0:
                ratio = load[gpu_id] / free[gpu_id]
                if ratio < best_ratio:
                    best_ratio, best_idx = ratio, gpu_id
        if best_idx is None:
            return None
        placement[best_idx].append(model)
        load[best_idx] += model.req_rate / model.slo
        free[best_idx] -= model.model_size
    return placement


def _swap_refine(placement):
    """One pass: swap a model between the worst-KVPR GPU and another GPU
    whenever it lowers the overall max KVPR."""
    kvprs = {g: _kvpr(placement[g]) for g in placement}
    worst = max(placement, key=lambda g: kvprs[g])
    for m in list(placement[worst]):
        for g in placement:
            if g == worst:
                continue
            for m2 in list(placement[g]):
                if m.model_size - m2.model_size > sum(x.model_size for x in placement[g]) - GPU_MEM_SIZE:
                    continue
                if m2.model_size - m.model_size > sum(x.model_size for x in placement[worst]) - GPU_MEM_SIZE:
                    continue
                placement[worst].remove(m); placement[worst].append(m2)
                placement[g].remove(m2); placement[g].append(m)
                if max(_kvpr(v) for v in placement.values()) < max(kvprs.values()) - 1e-12:
                    return _swap_refine(placement)
                placement[worst].remove(m2); placement[worst].append(m)
                placement[g].remove(m); placement[g].append(m2)
    return placement


def _move_refine(placement):
    """Hill-climb: repeatedly move a model off the worst-KVPR GPU to any
    other GPU whenever it lowers the overall max KVPR."""
    for _ in range(200):
        kvprs = {g: _kvpr(placement[g]) for g in placement}
        worst = max(placement, key=lambda g: kvprs[g])
        if kvprs[worst] <= 0:
            break
        improved = False
        for m in list(placement[worst]):
            for g in placement:
                if g == worst:
                    continue
                if m.model_size > GPU_MEM_SIZE - sum(x.model_size for x in placement[g]):
                    continue
                placement[worst].remove(m)
                placement[g].append(m)
                if max(_kvpr(v) for v in placement.values()) < max(kvprs.values()) - 1e-12:
                    improved = True
                    break
                placement[g].remove(m)
                placement[worst].append(m)
            if improved:
                break
        if not improved:
            break
    return placement


def compute_model_placement(gpu_num, models):
    """
    Best-of-4 greedy KVPR-minimizing placement: run the greedy (each model
    goes to the fittable GPU with lowest current KVPR) under four model
    orderings, keep the placement with the lowest max KVPR, then improve it
    with a bounded swap-based local search between the worst GPU and others,
    followed by a move-based hill climb off the worst GPU.
    """
    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) * m.model_size, reverse=True),
        sorted(models, key=lambda m: m.req_rate, reverse=True),
        sorted(models, key=lambda m: m.slo),
    ]
    best, best_max = None, float('inf')
    for ms in orders:
        p = _greedy(gpu_num, ms)
        if p is None:
            continue
        p = _move_refine(_swap_refine(p))
        mx = max(_kvpr(v) for v in p.values())
        if mx < best_max:
            best, best_max = p, mx
    if best is None:
        raise ValueError("Unable to place all models within GPU memory")
    return _move_refine(_swap_refine(best))

